package com.careerassistant.roadmap;
import com.careerassistant.ai.GeminiClient; import com.careerassistant.common.ApiException; import com.careerassistant.security.CurrentUser; import com.careerassistant.user.UserAccount;
import com.fasterxml.jackson.databind.JsonNode; import jakarta.persistence.*; import jakarta.validation.Valid; import jakarta.validation.constraints.NotBlank; import jakarta.validation.constraints.NotNull; import org.springframework.data.jpa.repository.JpaRepository; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.bind.annotation.*; import java.time.*; import java.util.*;
@Entity @Table(name="learning_roadmaps") class LearningRoadmap{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)Long id;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="user_id")UserAccount user;String title;@Column(name="target_role")String targetRole;@Column(name="created_at")Instant createdAt=Instant.now();}
@Entity @Table(name="roadmap_tasks") class RoadmapTask{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)Long id;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="roadmap_id")LearningRoadmap roadmap;@Column(name="phase_name")String phaseName;String topic;String status="PENDING";@Column(name="due_date")LocalDate dueDate;}
interface LearningRoadmapRepository extends JpaRepository<LearningRoadmap,Long>{List<LearningRoadmap> findByUserIdOrderByCreatedAtDesc(Long userId);Optional<LearningRoadmap> findByIdAndUserId(Long id,Long uid);}
interface RoadmapTaskRepository extends JpaRepository<RoadmapTask,Long>{List<RoadmapTask> findByRoadmapId(Long id);Optional<RoadmapTask> findByIdAndRoadmapUserId(Long id,Long uid);}
@Service class RoadmapService{
 private final LearningRoadmapRepository roadmaps;private final RoadmapTaskRepository tasks;private final GeminiClient gemini;
 RoadmapService(LearningRoadmapRepository r,RoadmapTaskRepository t,GeminiClient g){roadmaps=r;tasks=t;gemini=g;}
 @Transactional RoadmapView generate(UserAccount user,GenerateRequest r){JsonNode output=gemini.generateJson("Create a personalized learning roadmap for a "+r.targetRole()+" based on current skills: "+r.currentSkills()+". Return JSON {title:string,tasks:[{phase:string,topic:string,week:integer}]}. Use only actionable study topics.");if(!output.path("tasks").isArray()||output.path("tasks").isEmpty())throw ApiException.serviceUnavailable("Gemini returned an invalid roadmap schema.");LearningRoadmap roadmap=new LearningRoadmap();roadmap.user=user;roadmap.targetRole=r.targetRole();roadmap.title=output.path("title").asText(r.targetRole()+" learning roadmap");roadmaps.save(roadmap);for(JsonNode task:output.path("tasks")){RoadmapTask entity=new RoadmapTask();entity.roadmap=roadmap;entity.phaseName=task.path("phase").asText("Learning");entity.topic=task.path("topic").asText();int week=Math.max(1,task.path("week").asInt(1));entity.dueDate=LocalDate.now().plusWeeks(week);if(!entity.topic.isBlank())tasks.save(entity);}return view(roadmap);}
 List<RoadmapView> list(UserAccount user){return roadmaps.findByUserIdOrderByCreatedAtDesc(user.getId()).stream().map(this::view).toList();}
 TaskView update(UserAccount user,Long id,TaskUpdate r){RoadmapTask t=tasks.findByIdAndRoadmapUserId(id,user.getId()).orElseThrow(()->ApiException.notFound("Roadmap task not found."));t.status=r.completed()?"COMPLETED":"PENDING";tasks.save(t);return task(t);}
 private RoadmapView view(LearningRoadmap r){List<TaskView> list=tasks.findByRoadmapId(r.id).stream().map(this::task).toList();long done=list.stream().filter(x->x.status.equals("COMPLETED")).count();return new RoadmapView(r.id,r.title,r.targetRole,r.createdAt,list,list.isEmpty()?0:(int)(100*done/list.size()));}
 private TaskView task(RoadmapTask t){return new TaskView(t.id,t.phaseName,t.topic,t.status,t.dueDate);}
 record GenerateRequest(@NotBlank String targetRole,@NotBlank String currentSkills){} record TaskUpdate(@NotNull Boolean completed){} record TaskView(Long id,String phase,String topic,String status,LocalDate dueDate){} record RoadmapView(Long id,String title,String targetRole,Instant createdAt,List<TaskView> tasks,int progress){}
}
@RestController @RequestMapping("/api/roadmaps") class RoadmapController{private final RoadmapService service;RoadmapController(RoadmapService s){service=s;}@PostMapping("/generate")RoadmapService.RoadmapView generate(@Valid @RequestBody RoadmapService.GenerateRequest r){return service.generate(CurrentUser.require(),r);}@GetMapping List<RoadmapService.RoadmapView> list(){return service.list(CurrentUser.require());}@PutMapping("/tasks/{id}")RoadmapService.TaskView update(@PathVariable Long id,@Valid @RequestBody RoadmapService.TaskUpdate r){return service.update(CurrentUser.require(),id,r);}}
